import React, { useState, useEffect } from 'react';
import axios from 'axios';

const TripBudgetDashboard = () => {
  const [trips, setTrips] = useState([]);
  const [activeTrip, setActiveTrip] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [showCreateTrip, setShowCreateTrip] = useState(false);
  const [showBudgetCalculator, setShowBudgetCalculator] = useState(false);

  const [tripForm, setTripForm] = useState({ trip_purpose: '', destination_city: '', start_date: '', end_date: '' });
  const [calculatorForm, setCalculatorForm] = useState({ destination_city: '', start_date: '', end_date: '' });
  const [calculatedBudget, setCalculatedBudget] = useState(null);

  useEffect(() => { fetchTrips(); fetchActiveTrip(); }, []);

  const fetchTrips = async () => {
    try {
      const token = localStorage.getItem('token');
      const response = await axios.get('http://localhost:8000/trip-budget/my-trips', { headers: { Authorization: `Bearer ${token}` } });
      if (response.data.success) setTrips(response.data.trips);
    } catch (err) {
      console.error('Error fetching trips:', err); setError('Failed to load trips');
    }
  };

  const fetchActiveTrip = async () => {
    try {
      const token = localStorage.getItem('token');
      const response = await axios.get('http://localhost:8000/trip-budget/active-trip', { headers: { Authorization: `Bearer ${token}` } });
      if (response.data.success && response.data.active_trip) setActiveTrip(response.data.active_trip);
    } catch (err) {
      console.error('Error fetching active trip:', err);
    } finally { setLoading(false); }
  };

  const handleCreateTrip = async (e) => {
    e.preventDefault();
    try {
      const token = localStorage.getItem('token');
      const response = await axios.post('http://localhost:8000/trip-budget/create-trip', tripForm, { headers: { Authorization: `Bearer ${token}` } });
      if (response.data.success) {
        alert('Trip request created successfully! Waiting for manager approval.');
        setShowCreateTrip(false);
        setTripForm({ trip_purpose: '', destination_city: '', start_date: '', end_date: '' });
        fetchTrips();
      }
    } catch (err) {
      console.error('Error creating trip:', err);
      alert('Failed to create trip request: ' + (err.response?.data?.detail || err.message));
    }
  };

  const handleCalculateBudget = async (e) => {
    e.preventDefault();
    try {
      const token = localStorage.getItem('token');
      const response = await axios.get('http://localhost:8000/trip-budget/budget-calculator', { params: calculatorForm, headers: { Authorization: `Bearer ${token}` } });
      if (response.data.success) setCalculatedBudget(response.data.calculation);
    } catch (err) {
      console.error('Error calculating budget:', err);
      alert('Failed to calculate budget: ' + (err.response?.data?.detail || err.message));
    }
  };

  const handleActivateTrip = async (tripId) => {
    try {
      const token = localStorage.getItem('token');
      const response = await axios.post(`http://localhost:8000/trip-budget/activate-trip?trip_id=${tripId}`, {}, { headers: { Authorization: `Bearer ${token}` } });
      if (response.data.success) { alert('Trip activated! You can now submit expenses.'); fetchActiveTrip(); fetchTrips(); }
    } catch (err) { console.error('Error activating trip:', err); alert('Failed to activate trip: ' + (err.response?.data?.detail || err.message)); }
  };

  const handleCompleteTrip = async (tripId) => {
    try {
      const token = localStorage.getItem('token');
      const response = await axios.post(`http://localhost:8000/trip-budget/complete-trip?trip_id=${tripId}`, {}, { headers: { Authorization: `Bearer ${token}` } });
      if (response.data.success) { alert('Trip marked as completed!'); fetchActiveTrip(); fetchTrips(); }
    } catch (err) { console.error('Error completing trip:', err); alert('Failed to complete trip: ' + (err.response?.data?.detail || err.message)); }
  };

  const formatCurrency = (amount) => new Intl.NumberFormat('en-IN', { style: 'currency', currency: 'INR', minimumFractionDigits: 0, maximumFractionDigits: 0 }).format(amount || 0);
  const getProgressPercentage = (used, allocated) => !allocated ? 0 : Math.min((used / allocated) * 100, 100);
  const getProgressColor = (p) => p >= 90 ? '#dc3545' : p >= 70 ? '#ffc107' : '#28a745';
  const getStatusColor = (status) => ({ pending: '#ffc107', approved: '#28a745', active: '#007bff', completed: '#6c757d', cancelled: '#dc3545' }[status] || '#6c757d');

  if (loading) return (
    <div className="container-page"><div className="content-card loading-container"><div className="loading-spinner"></div><p>Loading trip information...</p></div></div>
  );

  return (
    <div className="container-page">
      <div className="page-header">
        <div className="title">🧳 Trip Budget Management</div>
        <div className="subtitle">Manage your official company trips and expense budgets</div>
      </div>

      {/* Active Trip */}
      {activeTrip ? (
        <div className="active-trip-section">
          <div className="active-trip-card card-hover">
            <div className="grid grid-2">
              <div>
                <div className="page-title">Trip to {activeTrip.destination}</div>
                <div className="text-muted">{new Date(activeTrip.trip_start).toLocaleDateString()} - {new Date(activeTrip.trip_end).toLocaleDateString()}</div>
              </div>
              <div className="action-buttons" style={{ justifyContent: 'flex-end' }}>
                <button className="btn btn-primary" onClick={() => window.location.href = '/upload'}>📤 Submit Expense</button>
                <button className="btn btn-outline" onClick={() => handleCompleteTrip(activeTrip.trip_id)}>✅ Complete Trip</button>
              </div>
            </div>

            <div className="section">
              {Object.entries(activeTrip.allocated_budgets).map(([type, allocated]) => {
                const used = activeTrip.used_budgets[type] || 0;
                const remaining = activeTrip.remaining_budgets[type] || allocated;
                const percentage = getProgressPercentage(used, allocated);
                return (
                  <div key={type} className="card" style={{ marginBottom: 12 }}>
                    <div className="grid" style={{ gridTemplateColumns: '1fr auto' }}>
                      <div><strong>{type.replace('_',' ').toUpperCase()}</strong></div>
                      <div className="text-muted">{formatCurrency(used)} / {formatCurrency(allocated)}</div>
                    </div>
                    <div className="progress" style={{ marginTop: 8 }}>
                      <div className="progress-bar" style={{ width: `${percentage}%`, backgroundColor: getProgressColor(percentage) }}></div>
                    </div>
                    <div className="text-muted" style={{ marginTop: 6 }}>Remaining: <strong>{formatCurrency(remaining)}</strong></div>
                  </div>
                );
              })}
            </div>
          </div>
        </div>
      ) : (
        <div className="content-card"><div className="page-title">📋 No Active Trip</div><div className="text-muted">You can only submit expenses during approved company trips. Create a trip request to get started.</div></div>
      )}

      {/* Actions */}
      <div className="action-buttons" style={{ margin: '16px 0' }}>
        <button className="btn btn-primary" onClick={() => setShowCreateTrip(true)}>➕ Create Trip Request</button>
        <button className="btn btn-secondary" onClick={() => setShowBudgetCalculator(true)}>🧮 Calculate Budget</button>
      </div>

      {/* All Trips */}
      <div className="content-card">
        <div className="page-title">📋 All Trips</div>
        {trips.length === 0 ? (
          <div className="text-muted">No trips found. Create your first trip request!</div>
        ) : (
          <div className="trips-grid">
            {trips.map((trip) => (
              <div key={trip.trip_id} className="trip-card card-hover">
                <div className="grid" style={{ gridTemplateColumns: '1fr auto' }}>
                  <div className="page-title" style={{ margin: 0 }}>{trip.purpose}</div>
                  <span className="badge" style={{ backgroundColor: getStatusColor(trip.status) }}>{trip.status.toUpperCase()}</span>
                </div>
                <div className="section">
                  <div><strong>Destination:</strong> {trip.destination} ({trip.destination_tier.replace('_', ' ')})</div>
                  <div><strong>Duration:</strong> {trip.duration_days} days</div>
                  <div><strong>Dates:</strong> {new Date(trip.start_date).toLocaleDateString()} - {new Date(trip.end_date).toLocaleDateString()}</div>
                  <div><strong>Total Budget:</strong> {formatCurrency(trip.total_allocated)}</div>
                  <div><strong>Expenses Submitted:</strong> {formatCurrency(trip.expenses_submitted)}</div>
                  <div><strong>Remaining:</strong> {formatCurrency(trip.remaining_budget)}</div>
                </div>
                <div className="action-buttons">
                  {trip.status === 'approved' && (<button className="btn btn-primary btn-small" onClick={() => handleActivateTrip(trip.trip_id)}>🚀 Activate Trip</button>)}
                  {trip.status === 'active' && (<button className="btn btn-outline btn-small" onClick={() => handleCompleteTrip(trip.trip_id)}>✅ Complete</button>)}
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Create Trip Modal */}
      {showCreateTrip && (
        <div className="modal-overlay" onClick={() => setShowCreateTrip(false)}>
          <div className="modal" onClick={(e) => e.stopPropagation()}>
            <div className="modal-header">
              <h3>Create Trip Request</h3>
              <button className="close-btn" onClick={() => setShowCreateTrip(false)}>×</button>
            </div>
            <div className="modal-body">
              <form onSubmit={handleCreateTrip} className="form">
                <div className="form-group">
                  <label className="form-label">Trip Purpose</label>
                  <input className="form-control" type="text" value={tripForm.trip_purpose} onChange={(e) => setTripForm({ ...tripForm, trip_purpose: e.target.value })} placeholder="e.g., Client meeting, Conference, Training" required />
                </div>
                <div className="form-row columns-2">
                  <div className="form-group">
                    <label className="form-label">Destination City</label>
                    <input className="form-control" type="text" value={tripForm.destination_city} onChange={(e) => setTripForm({ ...tripForm, destination_city: e.target.value })} placeholder="e.g., Mumbai, Delhi, Bangalore" required />
                  </div>
                  <div className="form-group">
                    <label className="form-label">Start Date</label>
                    <input className="form-control" type="date" value={tripForm.start_date} onChange={(e) => setTripForm({ ...tripForm, start_date: e.target.value })} min={new Date().toISOString().split('T')[0]} required />
                  </div>
                  <div className="form-group">
                    <label className="form-label">End Date</label>
                    <input className="form-control" type="date" value={tripForm.end_date} onChange={(e) => setTripForm({ ...tripForm, end_date: e.target.value })} min={tripForm.start_date || new Date().toISOString().split('T')[0]} required />
                  </div>
                </div>
                <div className="action-buttons" style={{ justifyContent: 'flex-end' }}>
                  <button type="button" className="btn btn-secondary" onClick={() => setShowCreateTrip(false)}>Cancel</button>
                  <button type="submit" className="btn btn-primary">Create</button>
                </div>
              </form>
            </div>
          </div>
        </div>
      )}

      {/* Budget Calculator Modal */}
      {showBudgetCalculator && (
        <div className="modal-overlay" onClick={() => setShowBudgetCalculator(false)}>
          <div className="modal" onClick={(e) => e.stopPropagation()}>
            <div className="modal-header">
              <h3>Budget Calculator</h3>
              <button className="close-btn" onClick={() => setShowBudgetCalculator(false)}>×</button>
            </div>
            <div className="modal-body">
              <form onSubmit={handleCalculateBudget} className="form">
                <div className="form-row columns-2">
                  <div className="form-group">
                    <label className="form-label">Destination City</label>
                    <input className="form-control" type="text" value={calculatorForm.destination_city} onChange={(e) => setCalculatorForm({ ...calculatorForm, destination_city: e.target.value })} required />
                  </div>
                  <div className="form-group">
                    <label className="form-label">Start Date</label>
                    <input className="form-control" type="date" value={calculatorForm.start_date} onChange={(e) => setCalculatorForm({ ...calculatorForm, start_date: e.target.value })} required />
                  </div>
                  <div className="form-group">
                    <label className="form-label">End Date</label>
                    <input className="form-control" type="date" value={calculatorForm.end_date} onChange={(e) => setCalculatorForm({ ...calculatorForm, end_date: e.target.value })} required />
                  </div>
                </div>
                <div className="action-buttons" style={{ justifyContent: 'flex-end' }}>
                  <button type="button" className="btn btn-secondary" onClick={() => setShowBudgetCalculator(false)}>Cancel</button>
                  <button type="submit" className="btn btn-primary">Calculate</button>
                </div>
              </form>

              {calculatedBudget && (
                <div className="content-card" style={{ marginTop: 16 }}>
                  <div className="page-title">Estimated Budget</div>
                  <div className="grid grid-2">
                    {Object.entries(calculatedBudget.allocated_budget || {}).map(([type, amount]) => (
                      <div key={type} className="card">
                        <div className="grid" style={{ gridTemplateColumns: '1fr auto' }}>
                          <div><strong>{type.replace('_', ' ').toUpperCase()}</strong></div>
                          <div>{formatCurrency(amount)}</div>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default TripBudgetDashboard;
